import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string}} assets
 * @property {any} cinematicPrimitives
 * @property {any} textContent
 * @property {any} neighbors
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {(url:string)=>Promise<any>} glbLoader
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {{fontAtlas:any}} fontAtlas
 */

/**
 * Creates a pricing card label sprite node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Load texture (grain map)
  const tex = ctx.textureLoader(config.assets?.imageUrl ?? '');

  // Determine plane size from atlas region (default aspect if unknown)
  const atlasRect = config.atlasRegion?.sourceRect ?? { width: 512, height: 320 };
  const aspect = atlasRect.width / atlasRect.height;

  const geometry = new THREE.PlaneGeometry(aspect, 1);

  const material = new MeshBasicNodeMaterial({
    map: texture(tex),
    toneMapping: THREE.NoToneMapping,
    transparent: true,
    depthTest: false,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Placement
  if (config.position) mesh.position.set(config.position.x, config.position.y, config.position.z);
  if (config.rotation) mesh.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  if (config.scale) mesh.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // Billboard toward camera
  mesh.onBeforeRender = function (_renderer, _scene, camera) {
    mesh.quaternion.copy(camera.quaternion);
  };

  // Apply cinematic primitives if any (none for this node, but keep contract)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(mesh, primitive.params);
      }
    }
  }

  // Event handlers container (none defined)
  mesh.userData.handlers = {};

  // Cleanup routine
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex && tex.dispose) tex.dispose();
    // Kill any GSAP timelines that might have been created (none in this node)
    gsap.globalTimeline.clear();
  };

  return mesh;
}
